sheet({title:'Stinger', units:'in'})

// Robots must fit inside the 18 x 18 x 18 box at the start of the match
box(-9,-9,0,  18,18,18,  {fill:C.white, alpha:0.15, limit:true})


// ---------- Variables ----------
const W  = 17,   L  = 17.5           // frame outside width (x) and length (y)
const T  = 2.76, H  = 4.5,  Z0 = 1   // rail thickness, rail height, bottom of the rails above the tiles
const th = 16 * Math.PI / 180        // ramp angle, radians
const RY = -8.25, RZ = 4.8, RF = 2.5 // roller: axle y, axle z, how far the tubing sticks out past the core
const SX = 0, SY = 0.6, SZ = 2.28    // spindexer centre x,y and the plate's underside (sits on the cross member)
const SR = 4.92, PR = 2.94, CR = 1.18 // plate radius, pocket radius, cup radius
const P  = 4                         // seconds between balls; also the time between spindexer steps
// turret: centre sits so the back pocket (transfer station) is directly under the wheel's entry point
const TX = SX, TY = SY + PR - 0.6, TZ = 4.2        // turret centre x,y; bottom of the bearing ring
const WR = 1.89, WZ = 9.8, WY = TY + 0.6            // flywheel radius (96 mm), axle height, axle y
const HG_P = 2.5, HG_N = 3.3                        // hood gap for pollen / nectar (ball minus ~0.3 squeeze)
const D2R = Math.PI/180


// ---------- Game pieces (not part of the robot: the size limit ignores them) ----------
const balls  = [pollen(0,-11), nectar(0,-15), pollen(0,-19), nectar(0,-23)]   // max 4 on board
const radii  = [1.40, 1.81, 1.40, 1.81]
const starts = [-11, -15, -19, -23]


// ---------- Chassis ----------
for (const x of [-8.06, 5.11]) {
  box(x, -L/2, 0,  T, L, H,  {fill:C.alu})            // rails start at the front edge
}
dim([-8.06, -L/2, H], [-8.06, L/2, H],  {off:40, text:`${L}" chassis length`})
dim([-8.06, -L/2, H], [-5.30, -L/2, H], {off:40, text:`${T}" rail width`})

for (const y of [-0.945, 6]) {
  box(-5.3, y, 1.81,  10.39, 1.89, 0.47,  {fill:C.alu})   // cross members
}
dim([-5.3, 6, 2.28], [5.09, 6, 2.28], {off:40})                       // 10.39
leader([0, 6, 2.28], 'cross member 1.89 × 0.47, 2×', 60, -50)

for (const x of [-7.43, 5.74]) {     // 104 mm mecanums, 0.63 in from each rail's left face
  for (const y of [-6.61, 6.61]) {
    cyl(x, y, 2.05,  2.05, 1.5,  {axis:'x', fill:C.dark})
  }
}
dim([-7.43, -6.61, 0],    [-7.43, -6.61, 4.1],  {off:-40})            // diameter 4.10
dim([-7.43, -6.61, 2.05], [-5.93, -6.61, 2.05], {off:40})             // width 1.50
leader([-7.43, -6.61, 4.1], '104 mm mecanum, 4×', -60, -40)


// ---------- Intake ----------
let fl = box(-5.3, -L/2, 0.3,  10.40, 7.04, 0.125,  {fill:C.blue})   // ramp
fl.rot[0] = 16
dim([-5.3, -L/2, 0.3], [5.1, -L/2, 0.3], {off:50})
leader([0, -5, 1.2], '16° ramp', 60, -40)

let gl = box(-5.0,  -L/2+0.4, 0.425,  0.125, 6, 1.5,  {fill:C.alu, part:fl})   // guides ride on the ramp
let gr = box(4.875, -L/2+0.4, 0.425,  0.125, 6, 1.5,  {fill:C.alu, part:fl})
gl.rot[2] = -25
gr.rot[2] =  25
dim([-2.35, -3.5, 1.8], [2.34, -3.5, 1.8], {off:-40})                 // throat ≈ 4.69

let rl = cyl(-4, RY, RZ,  0.75, 8,  {axis:'x', fill:C.dark})          // roller core
for (let i = 0; i < 12; i++) {
  const x = -3.5 + i*0.65
  const f = cyl(x, RY, RZ,  0.12, 0.75+RF,  {axis:'z', fill:C.yellow, part:rl, pivot:[x, RY, RZ]})
  f.rot[0] = (i % 2) * 180                                           // two rows, 180° apart
}
dim([-4, RY, 0], [-4, RY, RZ-0.75], {off:-60})                        // clearance under the core
leader([-4, RY, RZ+0.75+RF], 'tubing fingers, parked vertical at start', -60, -40)


// ---------- Spindexer ----------
let sp = part({pivot:[SX, SY, SZ]})
cyl(SX, SY, SZ,  SR, 0.25,  {axis:'z', fill:C.blue, part:sp})         // Ø9.85 plate
cyl(SX, SY, SZ+0.25,  0.6, 1.5,  {axis:'z', fill:C.alu, part:sp})     // centre post (short: the turret ring is above it)
for (let i = 0; i < 4; i++) {
  const a = (270 + i*90) * D2R                                       // pockets: front (fed by ramp), right, back (station), left
  cyl(SX + PR*Math.cos(a), SY + PR*Math.sin(a), SZ+0.2,  CR, 0.06,  {axis:'z', fill:C.dark, part:sp})   // pocket marker, flush
  const fin = box(SX+1.6, SY-0.08, SZ+0.25,  SR-1.9, 0.16, 1.4,  {fill:C.alu, part:sp, pivot:[SX, SY, SZ]})
  fin.rot[2] = 45 + i*90
}
dim([SX-SR, SY, SZ], [SX+SR, SY, SZ], {off:70, text:'Ø9.85 spindexer'})
dim([SX, SY, SZ+0.25], [SX, SY-PR, SZ+0.25], {off:-40, text:'R2.94 pockets'})


// ---------- Turret ----------
cyl(TX, TY, TZ,  4.9, 0.5,  {axis:'z', fill:C.dark, alpha:0.6})       // Ø9.8 bearing ring (fixed to the chassis)
let tur = part({pivot:[TX, TY, TZ+0.5]})                               // everything below turns with the turret
cyl(TX, TY, TZ+0.5,  4.9, 0.25,  {axis:'z', fill:C.blue, part:tur})   // turret plate

for (const x of [-2.4, 2.275]) {                                       // side plates, 4.8 apart, 1/8 thick
  box(x, TY-3.2, TZ+0.75,  0.125, 6.4, 8.3,  {fill:C.blue, alpha:0.35, part:tur})
}
// flywheels: two 96 mm wheels on one shaft across the plates
let fw = part({pivot:[0, WY, WZ]})      // shaft hub
fw.parent = tur                         // (the shaft turns with the turret; declared this way so fw can spin on its own)
cyl(-2.4, WY, WZ,  0.25, 4.8,  {axis:'x', fill:C.alu, part:fw})       // shaft
cyl(-1.5, WY, WZ,  WR, 1.0,  {axis:'x', fill:C.dark, part:fw})        // left wheel
cyl( 0.5, WY, WZ,  WR, 1.0,  {axis:'x', fill:C.dark, part:fw})        // right wheel
for (let i = 0; i < 4; i++) {                                          // spokes so you can see it spin
  box(-1.5, WY-0.1, WZ,  1.0, 0.2, WR-0.2,  {fill:C.alu, part:fw, pivot:[-1.5, WY, WZ]}).rot[0] = i*45
  box( 0.5, WY-0.1, WZ,  1.0, 0.2, WR-0.2,  {fill:C.alu, part:fw, pivot:[ 0.5, WY, WZ]}).rot[0] = i*45
}
for (const x of [-3.6, 2.4]) cyl(x, WY, WZ,  0.7, 1.2,  {axis:'x', fill:C.black, part:tur})   // the two motors, outside the plates

// hood: an arc round the wheel, radius = wheel + pollen gap. Three segments; the middle one slides out for nectar.
function arcProfile(a0, a1, R, thk) {
  const pts = []
  for (let a = a0; a <= a1; a += 5) pts.push([WY + R*Math.cos(a*D2R), WZ + R*Math.sin(a*D2R)])
  for (let a = a1; a >= a0; a -= 5) pts.push([WY + (R+thk)*Math.cos(a*D2R), WZ + (R+thk)*Math.sin(a*D2R)])
  return pts
}
const HR = WR + HG_P                                                   // hood radius for pollen
prism(arcProfile(280, 320, HR, 0.125), -2.2, 4.4, {axis:'x', fill:C.alu, part:tur})            // lower, fixed
let hm = prism(arcProfile(322, 353, HR, 0.125), -2.2, 4.4, {axis:'x', fill:C.yellow, part:tur}) // middle, retractable
prism(arcProfile(355, 390, HR, 0.125), -2.2, 4.4, {axis:'x', fill:C.alu, part:tur})            // upper, fixed

box(-1.4, TY-1.5, TZ+9.05,  2.8, 3.0, 1.2,  {fill:C.black, part:tur})   // Limelight on top (top at 14.45)

dim([TX-4.9, TY, TZ], [TX+4.9, TY, TZ], {off:60, text:'Ø9.8 bearing'})
dim([2.6, WY, WZ-WR], [2.6, WY, WZ+WR], {off:40, text:'Ø3.78 wheel'})
dim([-2.6, WY, WZ-WR], [-2.6, WY, WZ-HR], {off:-50, text:'gap 2.5 pollen / 3.3 nectar'})
leader([0, WY+HR, WZ+0.5], 'middle hood segment slides out 0.8 for nectar', 70, -60)
leader([0, TY, TZ+9.05+1.2], 'Limelight, top 14.45', -70, -40)


// ---------- Motion ----------
function index(t, period, move) {
  const k = Math.floor(t / period)
  const f = Math.min(1, (t - k*period) / move)
  const e = f*f*(3 - 2*f)
  return 90 * (k + e)
}

let feedR = 1.4   // radius of the ball currently being fed to the shooter (sets the hood gap)

// One ball's whole story. tb = its own clock (negative = waiting); k = which ball it is (0..3)
function journey(ball, r, y0, tb, k) {
  let x = 0, y, z
  const cupZ = SZ + 0.25 + r                                             // sitting on the plate in its pocket
  if (tb < 0)        { y = y0; z = r }                                                                   // waiting on the tiles
  else if (tb < 1.5) { y = y0 + tb/1.5 * (-8.75 - y0); z = r }                                           // dragged to the lip
  else if (tb < 3.5) { y = -8.75 + (tb-1.5)/2 * 6;  z = 0.425 + (y+8.75)*Math.tan(th) + r/Math.cos(th) } // up the ramp
  else if (tb < 3.8) { const f = (tb-3.5)/0.3; y = -2.75 + f*(SY-PR+2.75); z = 2.3 + f*(cupZ-2.3) }      // into the front pocket
  else {
    const ang = (270 + sp.rot[2] - 90*k) * D2R                           // riding its pocket round
    x = SX + PR*Math.cos(ang);  y = SY + PR*Math.sin(ang);  z = cupZ
    const tS = 3.8 + 2*P + 0.6                                           // at the back pocket = under the turret
    const Rb = WR + r - 0.3                                              // ball centre's radius round the wheel (0.3 squeeze)
    const zIn = WZ - Rb                                                  // entry point: straight below the wheel axle
    if (tb > tS) {                                                       // lift: straight up to the wheel
      feedR = r
      const f = Math.min(1, (tb-tS)/1.0)
      x = TX; y = WY; z = cupZ + f*(zIn - cupZ)
    }
    if (tb > tS + 1.0) {                                                 // round the hood: 270° → 390° (exits 60° up, forward)
      const f = Math.min(1, (tb-tS-1.0)/0.4), a = (270 + 120*f) * D2R
      x = TX; y = WY + Rb*Math.cos(a); z = WZ + Rb*Math.sin(a)
    }
    if (tb > tS + 1.4) {                                                 // flight: 18.5 ft/s at 60°, shown 4× slow
      const f = (tb-tS-1.4) * 0.25, v = 222, g = 386, a = 30*D2R
      const ey = WY + Rb*Math.cos(a), ez = WZ + Rb*Math.sin(a)
      x = TX; y = ey - v*Math.cos(60*D2R)*f; z = ez + v*Math.sin(60*D2R)*f - 0.5*g*f*f
    }
    if (tb > tS + 2.0) { x = 0; y = y0; z = r }                          // gone; back to the tiles for the next cycle
    // the turret is turned: rotate anything in the turret about its centre
    if (tb > tS) {
      const c = Math.cos(tur.rot[2]*D2R), s = Math.sin(tur.rot[2]*D2R), dx = x - TX, dy = y - TY
      x = TX + dx*c - dy*s;  y = TY + dx*s + dy*c
    }
  }
  ball.pos = [x, y - y0, z - r]
}

animate(t => {
  rl.rot[0]  = t * 360                         // intake roller, 1 turn/s
  fw.rot[0]  = t * 900                        // flywheel (slowed; real is 2500 rpm)
  tur.rot[2] = 15 * Math.sin(t * 0.4)          // turret tracking
  sp.rot[2]  = index(t - 3.8, P, 0.6)          // spindexer steps when a ball lands
  const tc = t % (4*P + 14)
  for (let k = 0; k < 4; k++) journey(balls[k], radii[k], starts[k], tc - k*P, k)
  // hood: middle segment slides radially out by 0.8 when the ball being fed is nectar
  const out = (feedR > 1.6) ? (HG_N - HG_P) : 0, am = 337.5*D2R
  hm.pos = [0, out*Math.cos(am), out*Math.sin(am)]
})
